<div class="table-wrap"><table><thead><tr><th><?= e(t('Date')) ?></th><th><?= e(t('Operation')) ?></th><th><?= e(t('Rice type')) ?></th><th><?= e(t('Warehouse')) ?></th><th class="number"><?= e(t('Quantity (တင်း)')) ?></th><th><?= e(t('Recorded by')) ?></th><th><?= e(t('Notes')) ?></th><th class="table-actions"><?= e(t('Actions')) ?></th></tr></thead><tbody>
<?php foreach($movements as $m): ?><tr><td><?= e($m['occurred_on']) ?></td><td><span class="badge <?= e($m['kind']) ?>"><?= e(t(ucfirst($m['kind']))) ?></span></td><td><strong><?= e($m['rice']) ?></strong></td><td><?= e($m['warehouse']) ?><?php if($m['destination']): ?><small>→ <?= e($m['destination']) ?></small><?php endif; ?></td><td class="number"><?= $m['kind']==='purchase'?'+':($m['kind']==='production'?'−':'') ?><?= e(num($m['quantity'])) ?></td><td><?= e($m['recorded_by']) ?></td><td class="notes-cell"><?= e($m['notes']?:'—') ?></td><td class="table-actions"><?php require __DIR__.'/operation-actions.php'; ?></td></tr><?php endforeach; ?>
<?php if(!$movements): ?><tr><td colspan="8" class="empty"><?= e(t('No stock activity yet. Record a purchase to begin.')) ?></td></tr><?php endif; ?></tbody></table></div>
